create table user_role_audit (id bigint primary key auto_increment, actor_user_id bigint not null, target_user_id bigint not null, operation varchar(32) not null, before_role varchar(32) not null, after_role varchar(32) not null, before_status varchar(32) not null, after_status varchar(32) not null, created_at datetime(6) not null, index idx_user_role_audit_target_created (target_user_id, created_at));
